{"sql": "WITH nums AS (
    SELECT generate_series(0, 230) AS n
)
SELECT date '1793-12-31' + (n * 365) * INTERVAL '1 day' AS dec31 FROM nums LIMIT 10", "preview_rows": 10}

{"sql": "WITH dec31 AS (
    SELECT UNNEST(generate_series(0, 230)) AS n
)
SELECT date '1793-12-31' + (n * 365) * INTERVAL '1 day' AS dec31 FROM dec31 LIMIT 10", "preview_rows": 10}

{"sql": "WITH years AS (
